// === Tab: mySketch ===
// #WCCChallenge
//
// Why is the sky blue?
//    ... I don't know.  (;´༎ຶ д ༎ຶ`)
//

let displaceWeight = 0.008;  // 0 to see p5
let noiseSpeed = 0.025;
let endFrame = 200;
let cloudAmount = 20;

let nativeShader;

let nativeLayer;
let bufferLayer;

let pos = [];

function preload(){
	nativeShader = createShader(vert, frag);
}

function setup() {
	createCanvas(1112, 834);
	pixelDensity(1);

	nativeLayer = createGraphics(width, height, WEBGL);
	bufferLayer = createGraphics(width, height);

	noStroke();
	nativeLayer.noStroke();
	bufferLayer.noStroke();
	bufferLayer.background("#FFFFFF");
	bufferLayer.rectMode(CENTER);

	for (let y = 0; y <= height; y += 6) {
		bufferLayer.fill( 0, map(noise(y), 0, 1, 160, 180), map(noise(y), 0, 1, 220, 255) );
		bufferLayer.rect(width/2, y, width, 5);
	}

	// cloud position
	for (let i = 0; i < cloudAmount; i++) {
		pos.push({
			x: random(width),
			y: random(height),
			direct: random([-1, 1]),
			speed: random(),
		});
	}
}

function draw() {
	for (let i = 0; i < cloudAmount; i++) {
		let posX = pos[i].x;
		let posY = pos[i].y;
		let dir = pos[i].direct;
		let t = frameCount*pos[i].speed;
		cloud(posX+dir*t, posY);
	}

	setShader(nativeLayer, nativeShader, bufferLayer);

	bufferLayer.image(nativeLayer, 0, 0);

	image(bufferLayer, 0, 0);

	/*if (frameCount === endFrame) {
		noLoop();
	}*/
}

function setShader(canvas, shader, buffer) {
	canvas.shader(shader);
	shader.setUniform('iResolution', [width, height]);
	shader.setUniform('iCanvas', buffer);
	shader.setUniform('iMouse', [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);
	shader.setUniform('iTime', frameCount);
	shader.setUniform('iDisplaceWeight', displaceWeight);
	shader.setUniform('iNoiseSpeed', noiseSpeed);
	canvas.rect(0, 0, width, height);
}

function cloud(posX, posY) {
	bufferLayer.push();
	bufferLayer.rectMode(CENTER);
	bufferLayer.translate(posX, posY);

	let xoff, yoff;
	let w, h = 20;
	let rad = 20;

	bufferLayer.fill(random(200,255), 5);

	for (let y = 0; y <= 100; y += 20) {
		xoff = map(noise(frameCount*0.01+y*10), 0, 1, -1, 1)*150;
		yoff = y;
		w = noise(frameCount*0.01+y*20)*150;
		bufferLayer.rect(xoff, yoff, w, h, rad);
	}

	bufferLayer.pop();
}

let lapse = 0;    // mouse timer
function mousePressed(){
// prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() +
    ".jpg");
    lapse = millis();
  }
}

