  vec4 snoise3DImage(vec2 uv, float scal, float gain, float ofst, vec3 move) {
    uv *= scal;
    float R = snoise(vec3(uv, 100.)+move);
    float G = snoise(vec3(uv, 300.)+move);
    float B = snoise(vec3(uv, 500.)+move);
    vec3 color = ofst+gain*vec3(R, G, B);
    return vec4(color, 1.);
  }

  vec4 snoise3DImage(vec2 uv, float scal, float gain, float ofst, float expo, vec3 move) {
    uv *= scal;
    float R = snoise(vec3(uv, 100.)+move);
    float G = snoise(vec3(uv, 300.)+move);
    float B = snoise(vec3(uv, 500.)+move);
    vec3 col;
    col.r = pow(abs(R), expo)*(step(0., R)*2.-1.);
    col.g = pow(abs(G), expo)*(step(0., G)*2.-1.);
    col.b = pow(abs(B), expo)*(step(0., B)*2.-1.);
    return vec4(ofst+gain*col, 1.);
  }
`


// === Tab: frag ===
// noprotect

const frag = `
  #ifdef GL_ES
  precision mediump float;
  #endif

  uniform vec2 iResolution;
  uniform sampler2D iCanvas;
  uniform vec2 iMouse;
  uniform float iTime;
  uniform float iDisplaceWeight;
  uniform float iNoiseSpeed;

  ${ snoise3D }
  ${ snoise3DImage }
  ${ displace }

  float random(vec2 uv) {
    return fract(sin(dot(uv, vec2(500.1234, -500.5678)))*9999.);
  }

  vec4 noise(vec2 uv, float scal, float gain, float ofst, float expo, vec3 move) {
    vec4 noise;
    noise  =     1.0*snoise3DImage((uv-vec2(421., 132))*1., scal, gain, ofst, move);
    noise +=     0.5*snoise3DImage((uv-vec2(913., 687))*2., scal, gain, ofst, move);
    noise +=    0.25*snoise3DImage((uv-vec2(834., 724))*4., scal, gain, ofst, move);
    noise +=   0.125*snoise3DImage((uv-vec2(125., 209))*8., scal, gain, ofst, move);
    noise +=  0.0625*snoise3DImage((uv-vec2(387., 99))*16., scal, gain, ofst, move);
    noise /= 1.9375;
    return noise;
  }

  varying vec2 vTexCoord;
  void main() {
    vec2 uv = vTexCoord;
    vec2 mouse = iMouse.xy/iResolution.xy;
    uv.y = 1.-uv.y;

    float scal = 40.;
    float gain = 1.;
    float ofst = .5;
    float expo = 1.;
    vec3  move = vec3(0., 0., iTime*iNoiseSpeed);
    vec4 dimg = noise(uv, scal, gain, ofst, expo, move);
    dimg *= (dimg+random(uv));

    float wei = iDisplaceWeight;
    vec2 duv = displace(uv, dimg.rg, ofst, wei);

    vec4 color = vec4(texture2D(iCanvas, duv).rgb, 1.);

    gl_FragColor = color;
  }
`


// === Tab: vert ===
// Basic structure ref: https://itp-xstory.github.io/p5js-shaders/#/./docs/how-to-write-a-shader

const vert = `
  #ifdef GL_ES
  precision mediump float;
  #endif

  attribute vec3 aPosition;
  attribute vec2 aTexCoord;

  varying vec2 vTexCoord;

  void main() {
    vTexCoord = aTexCoord;
    vec4 positionVec4 = vec4(aPosition, 1.0);
    positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
    gl_Position = positionVec4;
  }
`

